def a(url,label):return f'<a href="{E(url,quote=True)}">{label}</a>'
def table(head,rows,cls=''):
 return '<div class="table-wrap"><table class="'+cls+'"><thead><tr>'+''.join('<th scope="col">'+x+'</th>' for x in head)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+str(x)+'</td>' for x in row)+'</tr>' for row in rows)+'</tbody></table></div>'
def code(src,title,opened=False):
 return f'<details{" open" if opened else ""}><summary>{E(title)}</summary><p class="download"><a href="{src}" download>{E(src)}</a></p><pre><code>{E((EX/src).read_text())}</code></pre></details>'
def doc(lang,title,body,root=False):
 prefix='' if root else '../';other=('index_ru.html' if lang=='en' else 'index.html')
 linklabel='Русский' if lang=='en' else 'English'
 return f'''<!doctype html><html lang="{lang}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{E(title)} · LSSK</title><link rel="stylesheet" href="{prefix}style.css"><script src="{prefix}demo.js" defer></script></head><body>{body}<footer class="footer">{('Curriculum: Yuri Panchul / Verilog Meetup. Traffic-light idea: Timofei Nikiforov. Lesson, drawings and code prepared with Codex.' if lang=='en' else 'Программа: Юрий Панчул / Verilog Meetup. Идея светофора: Тимофей Никифоров. Урок, схемы и код подготовлены с помощью Codex.')}<br><a href="https://verilog-meetup.com/">verilog-meetup.com</a> · 2026-10-20 · <a href="{other}" hreflang="{'ru' if lang=='en' else 'en'}">{linklabel}</a></footer></body></html>'''
for lang in ['en','ru']:
 t=lambda en,ru:en if lang=='en' else ru
 idx='index.html' if lang=='en' else 'index_ru.html';other='index_ru.html' if lang=='en' else 'index.html'
 title=t('Timofei’s traffic light','Светофор Тимофея')
 b=['<header><div class="topbar">'+a('../'+idx,t('← Breadboard exercises','← Упражнения на макетной плате'))+a(other,t('Русский','English'))+'</div><div class="eyebrow">BB-FSM-01 · Logic Synthesis School Kit</div><h1>'+title+'</h1><p class="intro">'+t('Build a ten-state machine with three CMOS chips. Then describe the same behavior in SystemVerilog and run it in simulation, on an FPGA and through a Tiny Tapeout wrapper.','Соберите автомат с десятью состояниями на трёх микросхемах CMOS. Затем опишите то же поведение на SystemVerilog и запустите его в симуляторе, на ПЛИС и через оболочку Tiny Tapeout.')+'</p><div class="stats"><span><strong>4 / 2 / 4</strong>'+t('red / yellow / green ticks','такта: красный / жёлтый / зелёный')+'</span><span><strong>3</strong>'+t('CMOS chips','микросхемы CMOS')+'</span><span><strong>10</strong>'+t('states in a cycle','состояний в цикле')+'</span></div></header><div class="layout"><nav class="toc" aria-label="'+t('Lesson sections','Разделы урока')+'"><strong>'+t('In this lesson','В этом уроке')+'</strong>']
 for n,h in enumerate(HEADINGS,1):b.append(a(f'#s{n:02d}',str(n)+'. '+h[0 if lang=='en' else 1]))
