 p(a('https://github.com/TinyTapeout/tt-demo-pcb','Official demoboard GPIO reference')+' · '+a('https://github.com/TinyTapeout/ttsky-verilog-template','Verilog template')+' · '+a('https://tinytapeout.com/guides/get-started-demoboard-etr/','Board setup guide'),a('https://github.com/TinyTapeout/tt-demo-pcb','Официальная таблица GPIO платы')+' · '+a('https://github.com/TinyTapeout/ttsky-verilog-template','Шаблон Verilog')+' · '+a('https://tinytapeout.com/guides/get-started-demoboard-etr/','Запуск платы'));end()
